"use client";

import { values } from "lodash";
import { useState } from "react";

type FormData = {
  name: string;
  mail: string;
  password: string;
};

export default function FormWithValidation2() {
  const [value, setValues] = useState<FormData>({
    name: "",
    mail: "",
    password: "",
  });

  const [errors, setErrors] = useState<Partial<FormData>>({});

  const handleOnChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setValues((prev) => ({ ...prev, [name]: value }));
  };

  return (
    <div className="flex justify-center items-center flex-col mx-auto">
      <div className="bg-gray-100 p-5 rounded-2xl">
        <form className="grid grid-cols-2 gap-2 mb-5">
          <label htmlFor="name">Name:</label>
          <input
            value={values.name}
            onChange={handleOnChange}
            className="bg-white p-1 border border-gray-300 rounded-lg"
            placeholder="name"
            name="name"
          />
          <label htmlFor="mail">mail:</label>
          <input
            type="mail"
            value={values.mail}
            onChange={handleOnChange}
            className="bg-white p-1 border border-gray-300 rounded-lg"
            placeholder="mail"
            name="mail"
          />
          <label htmlFor="password">password:</label>
          <input
            onChange={handleOnChange}
            className="bg-white p-1 border border-gray-300 rounded-lg"
            type="password"
            placeholder="password"
            name="password"
          />
        </form>
        <button className="w-full p-2 bg-blue-500 text-white rounded-lg">
          отправить
        </button>
      </div>
    </div>
  );
}
